/* Thème SPORTIF (« écrans de nuit » de Mat) : évacuation, remise des médailles, pause et bandeau d'attente. © Mat-et-Flo */
(function(){const st=document.createElement('style');st.textContent="@font-face{font-family:'SDInter';font-weight:600;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'SDInter';font-weight:800;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'SDInter';font-weight:900;src:url(data:font/woff2;base64,) format('woff2')}";document.head.appendChild(st)})();
(function(){
const GOLD=[245,197,66], RED=[255,84,84], ICE='#e4ecff';
const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x));
const f=n=>Math.round(n*100)/100;
const ease=x=>{x=clamp(x);return x*x*(3-2*x)};
const back=x=>{x=clamp(x);const c=1.9;return 1+(c+1)*Math.pow(x-1,3)+c*Math.pow(x-1,2)};
const mix=(a,b,k)=>`rgb(${a.map((v,i)=>Math.round(v+(b[i]-v)*k)).join(',')})`;
const rnd=i=>{const x=Math.sin(i*127.1+311.7)*43758.5453;return x-Math.floor(x)};


function bg(redK=0,pulse=0){
  return `<defs>
   <radialGradient id="g1" cx="15%" cy="0%" r="95%"><stop offset="0" stop-color="#1c3a78"/><stop offset=".4" stop-color="#102350"/><stop offset="1" stop-color="#08122b"/></radialGradient>
   <radialGradient id="g2" cx="50%" cy="48%" r="75%"><stop offset="0" stop-color="#b3141c" stop-opacity="${f(redK*(.55+pulse))}"/><stop offset="1" stop-color="#3a0509" stop-opacity="${f(redK*(.7+pulse))}"/></radialGradient>
  </defs><rect width="1600" height="900" fill="url(#g1)"/><rect width="1600" height="900" fill="url(#g2)"/>`;
}
function hdr(l,r,acc){
  return `<text x="96" y="104" font-size="46" font-weight="800" fill="#fff">${l}</text><text x="1504" y="104" text-anchor="end" font-size="46" font-weight="800" fill="${acc}">${r}</text><rect x="96" y="132" width="1408" height="4" fill="${acc}"/>`;
}

/* ===== ÉVACUATION ===== */
function fmtT(rem){const s=Math.max(0,Math.ceil(rem-1e-6));const m=Math.floor(s/60),ss=s%60;return String(m).padStart(2,'0')+':'+String(ss).padStart(2,'0')}
function sceneEvac(rem,t,total){
  const redK=ease((300-rem)/4);               // rouge dès 5:00
  const over=rem<=0;
  const urgent=rem<=60&&rem>0;
  const pulse=over?.12*Math.abs(Math.sin(t*5)):(redK>0?.05*Math.sin(t*3)+.05:0);
  const acc=mix(GOLD,RED,redK);
  let o=bg(redK,pulse);
  o+=hdr('ÉVACUATION DU BASSIN',P.tag||'RÉUNION',acc);
  const lab=over?'TEMPS ÉCOULÉ':"SORTIE DE L'EAU DANS";
  o+=`<text x="800" y="282" text-anchor="middle" font-size="54" font-weight="800" letter-spacing="12" fill="${over?'#fff':ICE}">${lab}</text>`;
  const blink=over?(Math.sin(t*6)>-.3?1:.35):1;
  const col=redK>.02?mix([255,255,255],[255,96,96],redK):'#fff';
  const sc=urgent?1+.012*Math.sin(t*2*Math.PI):1;
  o+=`<g transform="translate(800 640) scale(${f(sc)}) translate(-800 -640)" opacity="${f(blink)}"><text x="800" y="640" text-anchor="middle" font-size="410" font-weight="900" letter-spacing="8" fill="${col}" style="font-variant-numeric:tabular-nums;font-feature-settings:'tnum' 1">${fmtT(rem)}</text></g>`;
  const p=clamp(rem/total);
  o+=`<rect x="250" y="712" width="1100" height="16" rx="8" fill="rgba(255,255,255,.14)"/><rect x="250" y="712" width="${f(1100*p)}" height="16" rx="8" fill="${acc}"/>`;
  o+=`<text x="800" y="816" text-anchor="middle" font-size="40" font-weight="600" fill="${ICE}" opacity=".85">${over?"Veuillez quitter le bassin immédiatement":"Fin de l'échauffement · merci de sortir de l'eau"}</text>`;
  if(over) o+=`<rect x="20" y="20" width="1560" height="860" rx="26" fill="none" stroke="${mix(RED,RED,0)}" stroke-width="${f(10+6*Math.abs(Math.sin(t*5)))}" opacity="${f(.5+.4*Math.abs(Math.sin(t*5)))}"/>`;
  return o;
}

/* ===== MÉDAILLES ===== */
const MED={gold:['#fff1a8','#f2b81c','#a8760a'],silver:['#ffffff','#c7cfd9','#7d8798'],bronze:['#ffd9b0','#cd7f32','#7a4616']};
function medal(cx,cy,r,kind,label,age,t,idle){
  if(age==null){ // simple emplacement vide, discret
    return `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="rgba(228,236,255,.22)" stroke-width="4" stroke-dasharray="10 14"/><text x="${cx}" y="${cy+r+110}" text-anchor="middle" font-size="64" font-weight="800" fill="rgba(228,236,255,.25)">${label}</text>`;
  }
  const [c0,c1,c2]=MED[kind], id='m'+kind;
  const k=back(age/.7), sc=clamp(k,0,1.2), fl=Math.sin(t*1.6+cx)*5*(age>1?1:0);
  const y=cy+fl;
  let o=`<defs><radialGradient id="${id}" cx="35%" cy="28%" r="85%"><stop offset="0" stop-color="${c0}"/><stop offset=".55" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/></radialGradient>
   <linearGradient id="${id}s" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff" stop-opacity="0"/><stop offset=".5" stop-color="#fff" stop-opacity=".7"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient>
   <clipPath id="${id}c"><circle cx="0" cy="0" r="${r-6}"/></clipPath></defs>`;
  // halo
  o+=`<circle cx="${cx}" cy="${y}" r="${r*1.25*clamp(age/.8)}" fill="${c1}" opacity="${f(.07*clamp(age/.6))}"/>`;
  // anneau d'impact
  if(age<1.1) o+=`<circle cx="${cx}" cy="${y}" r="${r*(1+age*1.3)}" fill="none" stroke="${c0}" stroke-width="${f(8*(1-age/1.1))}" opacity="${f(1-age/1.1)}"/>`;
  // rayons or
  if(kind==='gold'){let rays='';for(let i=0;i<14;i++){const a=i/14*2*Math.PI+t*.25;rays+=`<path d="M0,0 L${f(Math.cos(a-.07)*r*1.9)},${f(Math.sin(a-.07)*r*1.9)} L${f(Math.cos(a+.07)*r*1.9)},${f(Math.sin(a+.07)*r*1.9)} Z"/>`}
    o+=`<g transform="translate(${cx} ${y})" fill="${c0}" opacity="${f(.07*clamp(age/.8))}">${rays}</g>`}
  o+=`<g transform="translate(${cx} ${y}) scale(${f(sc)})">`;
  // ruban
  o+=`<path d="M-${r*.55},-${r*.7} L-${r*.2},-${r*1.55} L${r*.2},-${r*1.55} L${r*.2},-${r*.5} Z" fill="#12307f" stroke="#fff" stroke-opacity=".25" stroke-width="3"/><path d="M${r*.55},-${r*.7} L${r*.2},-${r*1.55} L${r*.55},-${r*1.55} L${r*.9},-${r*.55} Z" fill="#d8343a"/>`;
  o+=`<circle r="${r}" fill="url(#${id})" stroke="rgba(0,0,0,.35)" stroke-width="5"/><circle r="${r*.8}" fill="none" stroke="rgba(0,0,0,.22)" stroke-width="5"/><circle r="${r*.8+5}" fill="none" stroke="rgba(255,255,255,.35)" stroke-width="3"/>`;
  o+=`<text y="${r*.3}" text-anchor="middle" font-size="${r*.95}" font-weight="900" fill="rgba(60,30,0,.55)">${label.replace(/[^0-9]/g,'')}</text>`;
  // reflet
  if(age<1.4){const sx=-r*1.6+age/1.2*r*3.4;o+=`<g clip-path="url(#${id}c)"><rect x="${f(sx)}" y="${-r}" width="${r*.5}" height="${r*2}" fill="url(#${id}s)" transform="rotate(20)"/></g>`}
  o+='</g>';
  // étincelles
  if(age<1.6)for(let i=0;i<10;i++){const a=rnd(i+(kind==='gold'?9:kind==='silver'?4:0))*6.28,d=r*(1+.9*age*(.6+rnd(i+3)));o+=`<path d="M${f(cx+Math.cos(a)*d)},${f(y+Math.sin(a)*d-9)} l3,9 l9,3 l-9,3 l-3,9 l-3,-9 l-9,-3 l9,-3 z" fill="#fff" opacity="${f((1-age/1.6)*(.5+.5*Math.sin(age*20+i)))}"/>`}
  o+=`<text x="${cx}" y="${cy+r+110}" text-anchor="middle" font-size="64" font-weight="800" fill="${c1}" opacity="${f(clamp((age-.3)/.4))}">${label}</text>`;
  return o;
}
function sceneMedal(u){
  let o=bg(0,0)+hdr('REMISE DES MÉDAILLES','CÉRÉMONIE PROTOCOLAIRE','#f5c542');
  const A={b:1.0,s:2.5,g:4.2}, age=k=>u>=A[k]?u-A[k]:null;
  o+=medal(800,470,155,'gold','1ᵉʳ',age('g'),u);
  o+=medal(1180,520,125,'bronze','3ᵉ',age('b'),u);
  o+=medal(420,500,135,'silver','2ᵉ',age('s'),u);
  return o;
}

/* ===== PAUSE ===== */
function scenePause(t){
  let o=bg(0,0)+hdr('COMPÉTITION','REPRISE BIENTÔT','#f5c542');
  // tasse + vapeur
  const cx=800,cy=380;
  let steam='';
  for(let i=0;i<3;i++){
    const x0=cx-50+i*50, ph=t*1.2+i*1.9;
    let d=`M${x0},${cy-70}`;
    for(let y=0;y<=110;y+=10){d+=` L${f(x0+Math.sin(ph-y*.06)*10*(.4+y/110))},${f(cy-70-y)}`}
    const op=.35+.35*Math.sin(t*1.5+i*2);
    steam+=`<path d="${d}" fill="none" stroke="#e4ecff" stroke-width="7" stroke-linecap="round" opacity="${f(op)}"/>`;
  }
  o+=steam;
  o+=`<g fill="none" stroke="#f5c542" stroke-width="10" stroke-linecap="round" stroke-linejoin="round"><path d="M${cx-115},${cy-40} H${cx+115} V${cy+40} Q${cx+115},${cy+118} ${cx},${cy+118} Q${cx-115},${cy+118} ${cx-115},${cy+40} Z" fill="rgba(245,197,66,.10)"/><path d="M${cx+115},${cy-18} Q${cx+185},${cy-18} ${cx+185},${cy+34} Q${cx+185},${cy+84} ${cx+105},${cy+84}"/><path d="M${cx-165},${cy+150} H${cx+165}"/></g>`;
  o+=`<text x="800" y="760" text-anchor="middle" font-size="190" font-weight="900" letter-spacing="14" fill="#fff">PAUSE</text>`;
  o+=`<text x="800" y="832" text-anchor="middle" font-size="42" font-weight="600" fill="${ICE}" opacity=".85">La compétition reprend dans quelques instants</text>`;
  return o;
}


/* ---------- adaptation Swim Direct ---------- */
const FT="font-family:SDInter,Inter,system-ui,sans-serif";
function evacSD(t,P){/* sur Swim Direct : sortie de l'eau immédiate + compte à rebours jusqu'au premier départ */
  const pulse=.06+.06*Math.sin(t*3);let o=bg(1,pulse);
  o+=hdr('ÉVACUATION DU BASSIN',P.tag||'',mix(GOLD,RED,1));
  const bl=Math.sin(t*6)>-.3?1:.35;
  o+=`<text x="800" y="300" text-anchor="middle" font-size="64" font-weight="900" letter-spacing="10" fill="#fff" opacity="${f(bl)}">SORTIE DE L'EAU IMMÉDIATE</text>`;
  if(P.cd){o+=`<text x="800" y="400" text-anchor="middle" font-size="40" font-weight="800" letter-spacing="10" fill="${ICE}">PREMIER DÉPART DANS</text>`;
    o+=`<text x="800" y="680" text-anchor="middle" font-size="300" font-weight="900" letter-spacing="6" fill="#fff" style="font-variant-numeric:tabular-nums;font-feature-settings:'tnum' 1">${P.cd}</text>`;
    if(P.at)o+=`<text x="800" y="770" text-anchor="middle" font-size="44" font-weight="700" fill="${ICE}" opacity=".85">à ${P.at}</text>`}
  o+=`<text x="800" y="840" text-anchor="middle" font-size="36" font-weight="600" fill="${ICE}" opacity=".85">Fin de l'échauffement · merci de sortir de l'eau</text>`;
  o+=`<rect x="20" y="20" width="1560" height="860" rx="26" fill="none" stroke="rgb(255,84,84)" stroke-width="${f(8+5*Math.abs(Math.sin(t*3)))}" opacity="${f(.35+.3*Math.abs(Math.sin(t*3)))}"/>`;
  return o}
function medalSD(u,P){let o=sceneMedal(u);if(P.sub)o+=`<text x="800" y="200" text-anchor="middle" font-size="40" font-weight="700" fill="${ICE}">${P.sub}</text>`;return o}
function pauseSD(t,P){let o=bg(0,0)+hdr('COMPÉTITION','REPRISE BIENTÔT','#f5c542');
  const p=scenePause(t);o+=p.slice(p.indexOf('<rect x="96" y="132"')).replace(/<rect x="96" y="132"[^>]*\/>/,'');
  if(P.cd)o=o.replace('La compétition reprend dans quelques instants','Reprise dans '+P.cd+(P.at?' · à '+P.at:''));
  else if(P.sub)o=o.replace('La compétition reprend dans quelques instants',P.sub);
  if(P.title&&P.title!=='PAUSE'){const fs=Math.min(190,Math.floor(1380/(P.title.length*.72)));o=o.replace('font-size="190" font-weight="900" letter-spacing="14" fill="#fff">PAUSE</text>','font-size="'+fs+'" font-weight="900" letter-spacing="'+(fs>120?14:4)+'" fill="#fff">'+P.title+'</text>')}/* titre long (nom de la pause) : réduit pour tenir dans l'écran */
  return o}
function waitSD(t,w,h){const W=1600,H=Math.max(160,W*h/w);let o=`<rect width="${W}" height="${f(H)}" fill="#0b1b3f"/>`;
  const N=3,LH=H/N;for(let i=0;i<N;i++){const y=i*LH;o+=`<rect y="${f(y)}" width="${W}" height="${f(LH)}" fill="${i%2?'#0f2a6c':'#12307f'}"/>`;
    for(let x=((t*50)%60)-60;x<W+30;x+=30){const k=Math.round((x-((t*50)%60))/30);o+=`<circle cx="${f(x)}" cy="${f(y+LH-6)}" r="5" fill="${k%3===1?'#fff':'#f5c542'}"/>`}
    const sx=((t*(160+i*40)+i*520)%(W+300))-150;o+=`<rect x="${f(sx-120)}" y="${f(y+LH*.35)}" width="120" height="${f(LH*.22)}" rx="${f(LH*.11)}" fill="url(#ws)"/><circle cx="${f(sx)}" cy="${f(y+LH*.46)}" r="${f(LH*.17)}" fill="#f5c542"/>`}
  return `<defs><linearGradient id="ws"><stop offset="0" stop-color="#f5c542" stop-opacity="0"/><stop offset="1" stop-color="#f5c542" stop-opacity=".6"/></linearGradient></defs>`+o.replace('<rect','<rect')}
window.MFA_T=window.MFA_T||{};window.MFA_T.sportif={render(svg,mode,P,t,w,h){
  if(mode==="wait"){const H=Math.max(160,1600*h/w);svg.setAttribute("preserveAspectRatio","xMidYMid slice");svg.setAttribute("viewBox",`0 0 1600 ${f(H)}`);svg.innerHTML=waitSD(t,w,h);return}
  const r=(w/h)||1.78;let VX=0,VY=0,VW=1600,VH=900;if(r<16/9){VH=1600/r;VY=(900-VH)/2}else{VW=900*r;VX=(1600-VW)/2}
  svg.setAttribute("preserveAspectRatio","xMidYMid meet");svg.setAttribute("viewBox",`${f(VX)} ${f(VY)} ${f(VW)} ${f(VH)}`);
  let o=mode==="evac"?evacSD(t,P):mode==="cer"?medalSD(t%12,P):pauseSD(t,P);
  o=o.replace(/<rect width="1600" height="900"/g,`<rect x="${f(VX)}" y="${f(VY)}" width="${f(VW)}" height="${f(VH)}"`);
  o=o.replace(/id="(g1|g2|m\w+?)"/g,`id="sd$1${mode}"`).replace(/url\(#(g1|g2|m\w+?)\)/g,`url(#sd$1${mode})`);/* ids propres à chaque écran : sinon un autre SVG de la page (évacuation rouge) colore la pause */
  svg.innerHTML=`<g style="${FT}">${o}</g>`}};
})();
